package com.jarvys.factory.runtime;
import java.util.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WidgetEngineTest {
    private static final String A=repeat('a'),B=repeat('b'),C=repeat('c'),D=repeat('d');
    static String repeat(char c){char[] chars=new char[64];Arrays.fill(chars,c);return new String(chars);}
    static class Memory implements WidgetLedger.Persistence {byte[] value;int writes;boolean fail;public Object lock(){return this;}public byte[] read(){return value==null?null:value.clone();}public void write(byte[] data)throws Exception{if(fail)throw new Exception("disk full");value=data.clone();writes++;}}
    static class Platform implements WidgetEngine.Platform {Set<Integer> own=new TreeSet<>(Arrays.asList(7,8,9));int calls,pins,validations;boolean supported=true,fail;int failAt;Runnable before;
        public Set<Integer> ownInstances(){return new TreeSet<>(own);}public boolean pinSupported(){return supported;}public void validate(WidgetModel model)throws FactoryException{validations++;}
        public boolean requestPin(WidgetModel model,NativeOperationAuthorization.Access live){live.check();pins++;if(fail)throw new IllegalStateException();return true;}
        public void update(WidgetLedger.Record row,NativeOperationAuthorization.Access live){if(before!=null)before.run();live.check();calls++;if(fail||calls==failAt)throw new IllegalStateException("binder unknown");}}
    static class Fixture {final Memory memory;final Platform platform=new Platform();final WidgetEngine.Source source;final WidgetLedger ledger;final WidgetEngine engine;
        Fixture(){this(new Memory(),A,B,WidgetModel.Limits.defaults());}Fixture(Memory m,String cert,String apk,WidgetModel.Limits limits){memory=m;source=new WidgetEngine.Source("com.example.widgets",cert,apk,C,1,limits);ledger=new WidgetLedger(m,source);engine=new WidgetEngine(source,ledger,platform);}}
    static WidgetModel text(String text)throws Exception{return WidgetModel.parse(new JSONObject().put("root",new JSONObject().put("type","text").put("text",text)),WidgetModel.Limits.ceiling());}
    static WidgetModel button(String mode)throws Exception{JSONObject node=new JSONObject().put("type","button").put("id","open").put("label","Open").put("data",new JSONObject().put("screen","details"));if(mode!=null)node.put("delivery",mode);return WidgetModel.parse(new JSONObject().put("root",node),WidgetModel.Limits.ceiling());}
    static WidgetRequest request(String action,WidgetModel model,boolean ack,int... ids)throws Exception{JSONArray array=new JSONArray();for(int id:ids)array.put(id);return WidgetRequest.parse(new JSONObject().put("action",action).put("widgetIds",array).put("model",model==null?JSONObject.NULL:model.details()).put("acknowledgeUnknown",ack),WidgetModel.Limits.ceiling());}
    static NativeOperationAuthorization.Access allow(){return ()->{};}
    interface Throwing{void run()throws Exception;}
    static void error(String code,Throwing body)throws Exception{try{body.run();fail("Expected "+code);}catch(FactoryException e){assertEquals(code,e.code);}}
    static String token(Fixture f)throws Exception{return f.ledger.read(7).tokens.get("open");}
    @Test public void defaultsAndCeilingsAreConfigurable(){assertEquals(16,WidgetModel.Limits.defaults().actions);assertEquals(64,WidgetModel.Limits.ceiling().actions);assertEquals(8,WidgetModel.Limits.ceiling().depth);}
    @Test public void typedTreeAcceptsAllPrimitives()throws Exception{JSONArray nodes=new JSONArray().put(new JSONObject().put("type","text").put("text","Hello" )).put(new JSONObject().put("type","image").put("asset","www/media/picture.png").put("description","Picture")).put(new JSONObject().put("type","progress").put("max",10).put("value",3).put("indeterminate",false)).put(button(null).root.details());WidgetModel model=WidgetModel.parse(new JSONObject().put("root",new JSONObject().put("type","row").put("children",nodes)),WidgetModel.Limits.defaults());assertEquals(4,model.root.children.size());assertEquals("repeatable",model.buttons.get(0).delivery);}
    @Test public void unknownTypesAndFieldsAreRejected()throws Exception{FactoryException typed=assertThrows(FactoryException.class,()->WidgetModel.parse("{\"root\":{\"type\":\"html\",\"text\":\"x\"}}",WidgetModel.Limits.defaults()));assertEquals("INVALID_ARGUMENT",typed.code);assertEquals("widgets.manage: model must contain supported bounded widget nodes with their documented fields.",typed.getMessage());JSONObject raw=text("x").details();raw.getJSONObject("root").put("url","https://example.test");error("INVALID_ARGUMENT",()->WidgetModel.parse(raw,WidgetModel.Limits.defaults()));}
    @Test public void noUriImageOrTraversal()throws Exception{for(String path:Arrays.asList("https://example.test/a.png","www/../a.png","www/a.svg","www/x%2f.png","/www/a.png")){JSONObject raw=new JSONObject().put("root",new JSONObject().put("type","image").put("asset",path).put("description",""));error("INVALID_ARGUMENT",()->WidgetModel.parse(raw,WidgetModel.Limits.defaults()));}}
    @Test public void payloadIsImmutableAndUnicodeValidated()throws Exception{JSONObject raw=button(null).details();WidgetModel model=WidgetModel.parse(raw,WidgetModel.Limits.defaults());raw.getJSONObject("root").getJSONObject("data").put("screen","hijacked");assertEquals("details",model.buttons.get(0).data().getString("screen"));model.buttons.get(0).data().put("screen","mutated");assertEquals("details",model.buttons.get(0).data().getString("screen"));raw.getJSONObject("root").getJSONObject("data").put("bad","\uD800");error("INVALID_ARGUMENT",()->WidgetModel.parse(raw,WidgetModel.Limits.defaults()));}
    @Test public void duplicateButtonIdsRejected()throws Exception{JSONObject b=button(null).root.details();JSONObject raw=new JSONObject().put("root",new JSONObject().put("type","column").put("children",new JSONArray().put(b).put(b)));error("INVALID_ARGUMENT",()->WidgetModel.parse(raw,WidgetModel.Limits.defaults()));}
    @Test public void depthEightWorksAndNineFails()throws Exception{JSONObject node=text("end").root.details();for(int i=1;i<8;i++)node=new JSONObject().put("type","column").put("children",new JSONArray().put(node));JSONObject eight=new JSONObject().put("root",node);assertNotNull(WidgetModel.parse(eight,WidgetModel.Limits.ceiling()));JSONObject nine=new JSONObject().put("root",new JSONObject().put("type","row").put("children",new JSONArray().put(node)));error("INVALID_ARGUMENT",()->WidgetModel.parse(nine,WidgetModel.Limits.ceiling()));}
    @Test public void actionCountCanExceedOriginalThree()throws Exception{JSONArray nodes=new JSONArray();for(int i=0;i<64;i++){JSONObject b=button(null).root.details();b.put("id","a"+i);nodes.put(b);}JSONObject raw=new JSONObject().put("root",new JSONObject().put("type","column").put("children",nodes));assertEquals(64,WidgetModel.parse(raw,WidgetModel.Limits.ceiling()).buttons.size());error("INVALID_ARGUMENT",()->WidgetModel.parse(raw,WidgetModel.Limits.defaults()));}
    @Test public void boundedSharedParserRetainsOldDefault()throws Exception{JSONObject o=new JSONObject().put("value",0);for(int i=0;i<12;i++)o=new JSONObject().put("child",o);String raw=o.toString();error("INVALID_REQUEST",()->StrictJson.object(raw,4096));assertNotNull(StrictJson.object(raw,4096,24,8192));error("INVALID_REQUEST",()->StrictJson.object("{\"x\":1,\"x\":2}",100,24,8192));}
    @Test public void requestBindsSortedExactOwnIdsAndModel()throws Exception{WidgetRequest one=request("update",text("one"),false,9,7);assertEquals(Arrays.asList(7,9),one.widgetIds);assertNotEquals(one.canonicalJson(),request("update",text("two"),false,9,7).canonicalJson());error("INVALID_ARGUMENT",()->request("update",text("one"),false,7,7));error("INVALID_ARGUMENT",()->request("remove",text("x"),false,7));}
    @Test public void invalidWidgetFieldNamesItsExpectedShape()throws Exception{try{WidgetRequest.parse(new JSONObject().put("action","update").put("widgetIds",new JSONArray().put("seven")).put("model",text("x").details()).put("acknowledgeUnknown",false),WidgetModel.Limits.defaults());fail();}catch(FactoryException failure){assertEquals("INVALID_ARGUMENT",failure.code);assertEquals("widgets.manage: widgetIds items must be positive integers.",failure.getMessage());}}
    @Test public void denyPerformsNoWriteRenderOrUpdate()throws Exception{Fixture f=new Fixture();try{f.engine.execute(request("update",text("secret"),false,7),()->{throw new SecurityException();});fail();}catch(SecurityException expected){}assertEquals(0,f.memory.writes);assertEquals(0,f.platform.calls);assertEquals(0,f.platform.validations);}
    @Test public void foreignInstanceRejectedBeforeReservation()throws Exception{Fixture f=new Fixture();error("NOT_OWN_WIDGET",()->f.engine.execute(request("update",text("x"),false,100),allow()));assertEquals(0,f.memory.writes);assertEquals(0,f.platform.calls);}
    @Test public void exactSuccessAndColdSnapshotRead()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",text("persist"),false,7),allow());Fixture cold=new Fixture(f.memory,A,B,WidgetModel.Limits.defaults());assertEquals("persist",cold.ledger.read(7).model.root.text);assertEquals("APPLIED",cold.engine.read(7).getString("state"));assertEquals("[7,8,9]",cold.engine.list().toString());}
    @Test public void unknownNeverBlindReplays()throws Exception{Fixture f=new Fixture();f.platform.fail=true;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",text("x"),false,7),allow()));assertEquals("DISPATCH_UNKNOWN",f.ledger.read(7).state);assertNull(f.engine.restorationRequest(7));f.platform.fail=false;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",text("x"),false,7),allow()));assertEquals(1,f.platform.calls);f.engine.execute(request("update",text("x"),true,7),allow());assertEquals(2,f.platform.calls);}
    @Test public void explicitUnknownAcknowledgementIsProgrammatic()throws Exception{Fixture f=new Fixture();f.platform.fail=true;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",button(null),false,7),allow()));f.platform.fail=false;f.engine.execute(request("remove",null,true,7),allow());assertEquals("RESET",f.ledger.read(7).state);}
    @Test public void deniedAfterReservationCannotApply()throws Exception{Fixture f=new Fixture();int[] checks={0};error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",text("x"),false,7),()->{if(++checks[0]>=3)throw new SecurityException();}));assertEquals(0,f.platform.calls);assertEquals("DISPATCH_UNKNOWN",f.ledger.read(7).state);}
    @Test public void partialMultiInstanceDispatchIsExplicit()throws Exception{Fixture f=new Fixture();f.platform.failAt=2;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",text("x"),false,7,8,9),allow()));assertEquals("APPLIED",f.ledger.read(7).state);assertEquals("DISPATCH_UNKNOWN",f.ledger.read(8).state);assertEquals("DISPATCH_UNKNOWN",f.ledger.read(9).state);assertEquals(2,f.platform.calls);}
    @Test public void failedDurableReservePreventsEffect()throws Exception{Fixture f=new Fixture();f.memory.fail=true;error("STORAGE_UNAVAILABLE",()->f.engine.execute(request("update",text("x"),false,7),allow()));assertEquals(0,f.platform.calls);}
    @Test public void failedCommitAfterEffectLeavesUnknown()throws Exception{Fixture f=new Fixture();f.platform.before=()->f.memory.fail=true;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("update",text("x"),false,7),allow()));assertEquals(1,f.platform.calls);f.memory.fail=false;assertEquals("DISPATCH_UNKNOWN",f.ledger.read(7).state);}
    @Test public void differentSignerCannotReadOrOverwrite()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",text("x"),false,7),allow());Fixture other=new Fixture(f.memory,D,B,WidgetModel.Limits.defaults());error("STORAGE_UNAVAILABLE",()->other.ledger.read(7));error("STORAGE_UNAVAILABLE",()->other.engine.execute(request("update",text("y"),false,7),allow()));assertEquals(0,other.platform.calls);}
    @Test public void sameSignerUpgradeNeedsFreshRestoreAndInvalidatesOldToken()throws Exception{Fixture old=new Fixture();old.engine.execute(request("update",button(null),false,7),allow());String token=token(old);Fixture updated=new Fixture(old.memory,A,D,WidgetModel.Limits.defaults());assertNull(updated.ledger.acceptTap(token,10,updated.platform.own));WidgetRequest restore=updated.engine.restorationRequest(7);assertNotNull(restore);assertTrue(updated.engine.restore(restore,allow()));assertEquals(D,updated.ledger.read(7).artifact);assertNull(updated.ledger.acceptTap(token,11,updated.platform.own));assertNotNull(updated.ledger.acceptTap(token(updated),12,updated.platform.own));}
    @Test public void deniedColdRestoreDoesNotUpdate()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",text("x"),false,7),allow());WidgetRequest restore=f.engine.restorationRequest(7);int writes=f.memory.writes;try{f.engine.restore(restore,()->{throw new SecurityException();});fail();}catch(SecurityException expected){}assertEquals(1,f.platform.calls);assertEquals(writes,f.memory.writes);}
    @Test public void changedModelAfterPolicyRequestCannotRestoreOldModel()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",text("old"),false,7),allow());WidgetRequest old=f.engine.restorationRequest(7);f.engine.execute(request("update",text("new"),false,7),allow());assertFalse(f.engine.restore(old,allow()));assertEquals(2,f.platform.calls);}
    @Test public void repeatableTapHasUniqueDeliveryEventsAndStablePoll()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());JSONObject first=f.ledger.acceptTap(token(f),10,f.platform.own),second=f.ledger.acceptTap(token(f),11,f.platform.own);assertNotEquals(first.getString("eventId"),second.getString("eventId"));assertEquals(first.toString(),f.ledger.poll().toString());assertEquals("at_least_once_delivery",first.getString("deliverySemantics"));assertFalse(first.has("token"));assertTrue(f.ledger.acknowledge(first.getString("eventId")));assertFalse(f.ledger.acknowledge(first.getString("eventId")));assertEquals(second.toString(),f.ledger.poll().toString());}
    @Test public void onceGenerationDuplicateCannotReenqueueAfterAck()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button("oncePerGeneration"),false,7),allow());String t=token(f);JSONObject event=f.ledger.acceptTap(t,1,f.platform.own);assertEquals(event.toString(),f.ledger.acceptTap(t,2,f.platform.own).toString());assertTrue(f.ledger.acknowledge(event.getString("eventId")));assertNull(f.ledger.acceptTap(t,3,f.platform.own));assertNull(f.ledger.poll());}
    @Test public void automaticRedrawPreservesOnceConsumedGeneration()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button("oncePerGeneration"),false,7),allow());String t=token(f);JSONObject e=f.ledger.acceptTap(t,1,f.platform.own);f.ledger.acknowledge(e.getString("eventId"));f.engine.restore(f.engine.restorationRequest(7),allow());assertEquals(t,token(f));assertNull(f.ledger.acceptTap(t,2,f.platform.own));}
    @Test public void unknownAndWrongOwnTokensDoNotEnterInbox()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());assertNull(f.ledger.acceptTap(A,1,f.platform.own));assertNull(f.ledger.acceptTap(token(f),1,Collections.singleton(8)));assertNull(f.ledger.poll());}
    @Test public void oldTokensInvalidatedByUpdateAndRemove()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());String old=token(f);f.engine.execute(request("update",button(null),false,7),allow());assertNull(f.ledger.acceptTap(old,10,f.platform.own));String newer=token(f);JSONObject result=f.engine.execute(request("remove",null,false,7),allow());assertFalse(result.getBoolean("launcherPlacementRemoved"));assertNull(f.ledger.acceptTap(newer,11,f.platform.own));assertTrue(f.engine.read(7).isNull("configuration"));assertTrue(f.platform.own.contains(7));}
    @Test public void inboxFullDoesNotConsumeOneShot()throws Exception{WidgetModel.Limits d=WidgetModel.Limits.defaults();WidgetModel.Limits l=new WidgetModel.Limits(d.instances,d.nodes,d.depth,d.actions,d.modelBytes,d.actionDataBytes,1,d.storageBytes,d.imageBytes,d.imagePixels);Fixture f=new Fixture(new Memory(),A,B,l);f.engine.execute(request("update",button("oncePerGeneration"),false,7,8),allow());JSONObject first=f.ledger.acceptTap(token(f),10,f.platform.own);String other=f.ledger.read(8).tokens.get("open");error("RESOURCE_LIMIT",()->f.ledger.acceptTap(other,11,f.platform.own));f.ledger.acknowledge(first.getString("eventId"));assertNotNull(f.ledger.acceptTap(other,12,f.platform.own));}
    @Test public void pendingEventsSurviveGenerationDeletion()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());JSONObject event=f.ledger.acceptTap(token(f),10,f.platform.own);f.ledger.deleted(new int[]{7});assertEquals(event.toString(),f.ledger.poll().toString());assertEquals(7,event.getInt("widgetId"));}
    @Test public void remapRequiresNewOwnedIdsAndFreshRestore()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());String old=token(f);f.ledger.remap(new int[]{7},new int[]{8},f.platform.own);assertNull(f.ledger.read(7));assertEquals("RESTORE_PENDING",f.ledger.read(8).state);assertNull(f.ledger.acceptTap(old,10,f.platform.own));assertTrue(f.engine.restore(f.engine.restorationRequest(8),allow()));assertEquals("APPLIED",f.ledger.read(8).state);}
    @Test public void remapNeverOverwritesAnotherConfiguration()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",text("x"),false,7,8),allow());error("CONFLICT",()->f.ledger.remap(new int[]{7},new int[]{8},f.platform.own));assertNotNull(f.ledger.read(7));assertNotNull(f.ledger.read(8));}
    @Test public void pinReportsRequestedNotPlacedAndNoPersistence()throws Exception{Fixture f=new Fixture();JSONObject result=f.engine.execute(request("requestPin",text("preview"),false),allow());assertEquals("requested",result.getString("state"));assertEquals(1,f.platform.pins);assertEquals(0,f.memory.writes);assertEquals(0,f.platform.calls);}
    @Test public void pinUnsupportedHasNoEffect()throws Exception{Fixture f=new Fixture();f.platform.supported=false;assertEquals("unsupported",f.engine.execute(request("requestPin",text("x"),false),allow()).getString("state"));assertEquals(0,f.platform.pins);}
    @Test public void pinFailureExplicitUnknown()throws Exception{Fixture f=new Fixture();f.platform.fail=true;error("DISPATCH_UNKNOWN",()->f.engine.execute(request("requestPin",text("x"),false),allow()));assertEquals(1,f.platform.pins);}
    @Test public void missedHostDeletionIsReconciledWithoutDiscardingInbox()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());JSONObject event=f.ledger.acceptTap(token(f),1,f.platform.own);f.platform.own.remove(7);f.engine.list();assertNull(f.ledger.read(7));assertEquals(event.toString(),f.ledger.poll().toString());assertEquals(1,f.platform.calls);}
    @Test public void budgetCapacityFailureMakesNoPlatformCall()throws Exception{WidgetModel.Limits d=WidgetModel.Limits.defaults();Fixture f=new Fixture(new Memory(),A,B,new WidgetModel.Limits(1,d.nodes,d.depth,d.actions,d.modelBytes,d.actionDataBytes,d.inboxEvents,d.storageBytes,d.imageBytes,d.imagePixels));f.engine.execute(request("update",text("x"),false,7),allow());error("RESOURCE_LIMIT",()->f.engine.execute(request("update",text("x"),false,8),allow()));assertEquals(1,f.platform.calls);assertNull(f.ledger.read(8));}
    @Test public void unconfirmedRemapDoesNotAcceptNewUndisplayedToken()throws Exception{Fixture f=new Fixture();f.engine.execute(request("update",button(null),false,7),allow());f.ledger.remap(new int[]{7},new int[]{8},f.platform.own);assertNull(f.ledger.acceptTap(f.ledger.read(8).tokens.get("open"),1,f.platform.own));}
    @Test public void malformedLedgerFailsClosedWithoutUpdate()throws Exception{Fixture f=new Fixture();f.memory.value="{bad}".getBytes(java.nio.charset.StandardCharsets.UTF_8);try{f.engine.execute(request("update",text("x"),false,7),allow());fail();}catch(FactoryException expected){}assertEquals(0,f.platform.calls);}

    @Test public void bridgeAdapterNormalizesOneUnifiedEffect()throws Exception{NativeWidgetEffects.Prepared p=NativeWidgetEffects.prepare("widgets.update",new JSONObject().put("widgetIds",new JSONArray().put(7)).put("model",text("x").details()));assertTrue(p.requiresSession());assertEquals("widgets.manage",p.operation());assertFalse(p.authorizationDetails().getBoolean("acknowledgeUnknown"));assertEquals("update",p.authorizationDetails().getString("action"));NativeWidgetEffects.Prepared read=NativeWidgetEffects.prepare("widgets.read",new JSONObject().put("widgetId",7));assertFalse(read.requiresSession());assertNull(read.operation());}
    @Test public void bridgeAdapterRejectsInjectedAuthorityAndNonBooleanAck()throws Exception{error("INVALID_ARGUMENT",()->NativeWidgetEffects.prepare("widgets.list",new JSONObject().put("allow",true)));error("INVALID_ARGUMENT",()->NativeWidgetEffects.prepare("widgets.remove",new JSONObject().put("widgetIds",new JSONArray().put(7)).put("acknowledgeUnknown","true")));}

    @Test public void bridgeAdapterEnforcesSignedLimitsBeforeExecution()throws Exception{WidgetModel.Limits d=WidgetModel.Limits.defaults();WidgetModel.Limits noButtons=new WidgetModel.Limits(d.instances,d.nodes,d.depth,0,d.modelBytes,d.actionDataBytes,d.inboxEvents,d.storageBytes,d.imageBytes,d.imagePixels);JSONObject raw=new JSONObject().put("model",button(null).details());error("INVALID_ARGUMENT",()->NativeWidgetEffects.prepare("widgets.requestPin",raw,noButtons));assertFalse(NativeWidgetEffects.prepare("widgets.list",new JSONObject(),noButtons).requiresSession());}

}
